import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 문서번호는 'FDR-일자-자금일보ID' 형식으로 채번한다 (채번 규칙 미정).
// 가정: 상신 가능한 현재 상태는 기안·반려·회수이다.
const SUBMITTABLE_STATUSES = ['기안', '반려', '회수'];

@Controller('api/v1')
export class FnSfr00903Controller {
  @Get('/fund-daily-reports')
  async listFundDailyReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const reportDate = q['reportDate'];
    if (typeof reportDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(reportDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자금일보 일자를 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const pageRaw = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const params = { reportDate, limit: size, offset: page * size };
      const rows = await db.query(
        `SELECT fund_daily_report_id AS "fundDailyReportId",
                to_char(report_date, 'YYYY-MM-DD') AS "reportDate",
                approval_status AS "approvalStatus"
           FROM fund_daily_report
          WHERE report_date = CAST(:reportDate AS date)
          ORDER BY fund_daily_report_id
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM fund_daily_report
          WHERE report_date = CAST(:reportDate AS date)`,
        { reportDate },
      );
      // TODO(질문): entries는 bank_transaction 기준이나 schema.sql에 해당 테이블이 없어 빈 배열로 둔다.
      const items = rows.map((r: any) => ({ ...r, entries: [] }));
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/fund-daily-reports/:fundDailyReportId/submit')
  @HttpCode(200)
  async submitFundDailyReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const idText = req.params['fundDailyReportId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(404, 'FUND_DAILY_REPORT_NOT_FOUND', '자금일보를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT fund_daily_report_id AS "fundDailyReportId",
                approval_status AS "approvalStatus"
           FROM fund_daily_report
          WHERE fund_daily_report_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FUND_DAILY_REPORT_NOT_FOUND', '자금일보를 찾을 수 없습니다.');
      }
      if (!SUBMITTABLE_STATUSES.includes(found[0]['approvalStatus'])) {
        throw new ApiError(409, 'FUND_DAILY_REPORT_ALREADY_SUBMITTED', '이미 상신되었거나 결재가 진행·완료된 자금일보입니다.');
      }
      // 가정: 사용 중이며 연계 결재가 가능한 결재양식 중 첫 번째를 쓴다.
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId"
           FROM approval_form
          WHERE use_status = '사용' AND is_linked_approval = true
          ORDER BY approval_form_id
          LIMIT 1`,
        {},
      );
      const emps = await db.query(
        `SELECT department_id AS "departmentId"
           FROM employee
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (forms.length === 0 || emps.length === 0 || emps[0]['departmentId'] === null) {
        throw new ApiError(502, 'APPROVAL_INTEGRATION_FAILED', '전자결재 연동에 실패했습니다. 결재양식 또는 기안부서를 확인하세요.');
      }
      const docs = await db.query(
        `INSERT INTO approval_document (
            approval_form_id, drafter_id, drafter_department_id, document_number, title,
            approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
            submitted_at, created_at, updated_at)
         SELECT CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
                'FDR-' || to_char(r.report_date, 'YYYYMMDD') || '-' || r.fund_daily_report_id,
                '자금일보 ' || to_char(r.report_date, 'YYYY-MM-DD'),
                '결재대기', false, false, '자금일보', r.fund_daily_report_id,
                now(), now(), now()
           FROM fund_daily_report r
          WHERE r.fund_daily_report_id = CAST(:id AS bigint)
         RETURNING approval_document_id AS "approvalDocumentId"`,
        { formId: forms[0]['approvalFormId'], userId: user.id, departmentId: emps[0]['departmentId'], id: idText },
      );
      const updated = await db.query(
        `UPDATE fund_daily_report
            SET approval_document_id = CAST(:docId AS bigint),
                approval_status = '결재대기',
                updated_at = now()
          WHERE fund_daily_report_id = CAST(:id AS bigint)
         RETURNING fund_daily_report_id AS "fundDailyReportId",
                   approval_document_id AS "approvalDocumentId",
                   approval_status AS "approvalStatus"`,
        { docId: docs[0]['approvalDocumentId'], id: idText },
      );
      return updated[0];
    });
  }
}

