import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  DateInput,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SUBMITTABLE = ['기안', '반려', '회수'];

export default function FnSfr00903Page({ role, notify }: PageProps) {
  const [reportDate, setReportDate] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [submitting, setSubmitting] = useState<Row | null>(null);
  const [filterError, setFilterError] = useState('');

  const { data, error, reload } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/fund-daily-reports', role, undefined, { reportDate: applied, page, size: 20 });
  }, [applied, page, role]);

  const items = data?.items ?? [];
  const waiting = items.filter((r) => r.approvalStatus === '결재대기' || r.approvalStatus === '진행중');

  const search = () => {
    if (!reportDate) {
      setFilterError('자금일보 일자를 입력하세요.');
      return;
    }
    setFilterError('');
    setPage(0);
    setApplied(reportDate);
  };

  const reset = () => {
    setReportDate('');
    setApplied('');
    setPage(0);
    setFilterError('');
  };

  const submitReport = async () => {
    if (!submitting) {
      return;
    }
    await call('POST', `/fund-daily-reports/${submitting.fundDailyReportId}/submit`, role, {});
    notify('자금일보를 결재 상신했습니다.');
    setSubmitting(null);
    setDetail(null);
    reload();
  };

  const entries = (detail?.entries as Row[] | undefined) ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['결재 진행', <Num value={waiting.length} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>자금일보</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="자금일보 일자" required>
            <DateInput value={reportDate} onChange={setReportDate} />
          </Field>
        </Filters>
        {filterError ? <p>{filterError}</p> : null}
        {error ? <p>{error}</p> : null}
        <Band total={data?.total ?? 0} />
        <DataTable
          columns={[
            { key: 'reportDate', label: '자금일보 일자', render: (r) => <DateText value={r.reportDate} /> },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                SUBMITTABLE.includes(String(r.approvalStatus)) ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setSubmitting(r);
                    }}
                  >
                    결재 상신
                  </button>
                ) : null,
            },
          ]}
          rows={items}
          onRowClick={(r) => setDetail(r)}
          empty="조회된 자금일보가 없습니다."
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>결재 진행 중</h2>
        <DataTable
          columns={[
            { key: 'reportDate', label: '일자', render: (r) => <DateText value={r.reportDate} /> },
            { key: 'approvalStatus', label: '상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
          rows={waiting}
          onRowClick={(r) => setDetail(r)}
          empty="진행 중인 결재가 없습니다."
        />
      </section>

      {detail ? (
        <Drawer title="자금일보 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['자금일보 일자', <DateText value={detail.reportDate} />],
              ['결재 진행 상태', <Badge value={detail.approvalStatus} />],
            ]}
          />
          <h3>일자별 입출금 및 잔액 내역</h3>
          <DataTable
            columns={[
              { key: 'depositAmount', label: '입금액', render: (r) => <Num value={r.depositAmount} /> },
              { key: 'withdrawalAmount', label: '출금액', render: (r) => <Num value={r.withdrawalAmount} /> },
              { key: 'balanceAmount', label: '잔액', render: (r) => <Num value={r.balanceAmount} /> },
            ]}
            rows={entries}
            empty="입출금 내역이 없습니다."
          />
          {SUBMITTABLE.includes(String(detail.approvalStatus)) ? (
            <button
              type="button"
              onClick={() => {
                setSubmitting(detail);
              }}
            >
              결재 상신
            </button>
          ) : null}
        </Drawer>
      ) : null}

      {submitting ? (
        <Drawer title="자금일보 결재 상신" onClose={() => setSubmitting(null)}>
          <Form
            onSubmit={submitReport}
            submit="결재 상신"
            note="상신하면 결재 진행 중에는 결재 절차 없이 수정할 수 없습니다."
          >
            <Pairs
              items={[
                ['자금일보 일자', <DateText value={submitting.reportDate} />],
                ['결재 진행 상태', <Badge value={submitting.approvalStatus} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
